package net.atlasauth.pca;

import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;

/**
 * Differential against the TS reference for the prohibition engine: test-data/k05-prohibitions.json.gz, generated by
 * tools/pca-audit/k05-oracles/prohibitions-oracle.mts (constitution and state validation, the monitor grids around every boundary,
 * advance, evidence, signed evidence, check-and-advance). Results compare as lenient canonical JSON (the reference's {ok, reason}
 * verdicts are rebuilt from the native String); a reference throw ({$throws}) requires a throw. Cases named {@code x:} hold a value the
 * canonical hash refuses (-0, an integer beyond 2^53-1, a lone surrogate) and replay together in {@link #exoticCases}.
 */
public class K05ProhibitionsDiffTest {
    static final String MODULE = "k05-prohibitions";

    @SuppressWarnings("unchecked") static Map<String, Object> m(Object o) { return (Map<String, Object>) o; }

    static byte[] seed(Object s) {
        byte[] b = Pca.decodeB64uStrict(s, -1);
        if (b == null) throw new IllegalArgumentException("bad seed");
        return b;
    }

    static Object verdict(String why) { return why == null ? Prohibitions.map("ok", true) : Prohibitions.map("ok", false, "reason", why); }

    interface Fn { Object apply(List<?> a) throws Exception; }

    static final Map<String, Fn> IMPL = new java.util.LinkedHashMap<>();
    static {
        IMPL.put("validateInvariant", a -> Prohibitions.validateInvariant(a.get(0)));
        IMPL.put("validateConstitution", a -> Prohibitions.validateConstitution(a.get(0)));
        IMPL.put("stateProblem", a -> Prohibitions.stateProblem(a.get(0)));
        IMPL.put("canonicalState", a -> Prohibitions.canonicalState(a.get(0)));
        IMPL.put("stateDigest", a -> Prohibitions.stateDigest(a.get(0)));
        IMPL.put("tickState", a -> Prohibitions.tickState(a.get(0), a.get(1)));
        IMPL.put("emptyState", a -> Prohibitions.emptyState(a.get(0)));
        IMPL.put("checkProhibitions", a -> Prohibitions.checkProhibitions(a.get(0), a.get(1), a.get(2)));
        IMPL.put("advanceStateStrict", a -> Prohibitions.advanceStateStrictRef(a.get(0), a.get(1), a.get(2), a.size() > 3 ? a.get(3) : Prohibitions.ABSENT));
        IMPL.put("proveSafety", a -> Prohibitions.proveSafety(a.get(0), a.get(1), a.get(2)));
        IMPL.put("verifySafetyEvidence", a -> verdict(Prohibitions.verifySafetyEvidence(a.get(0), a.get(1), a.get(2), a.get(3))));
        IMPL.put("safetyBindingId", a -> Prohibitions.safetyBindingId(m(a.get(0)), (String) a.get(1)));
        IMPL.put("signSafetyEvidence", a -> Prohibitions.signSafetyEvidence(a.get(0), seed(a.get(1)), (String) a.get(2)));
        IMPL.put("verifySignedSafetyEvidence", a -> verdict(Prohibitions.verifySignedSafetyEvidence(a.get(0), a.get(1))));
        IMPL.put("checkAndAdvance", a -> {
            Map<String, Object> o = a.size() > 4 ? m(a.get(4)) : null;
            String dg = o == null ? null : (String) o.get("expectedStateDigest");
            Object seq = o != null && o.containsKey("expectedSeq") ? o.get("expectedSeq") : Prohibitions.ABSENT;
            return Prohibitions.checkAndAdvanceRef((Boolean) a.get(0), a.get(1), a.get(2), a.get(3), seq, dg);
        });
        IMPL.put("verifyConstitution", a -> verdict(Prohibitions.verifyConstitution(a.get(0), a.size() > 1 ? (String) a.get(1) : null)));
        IMPL.put("constitutionId", a -> Prohibitions.constitutionId(m(a.get(0))));
        IMPL.put("whenAffirmative", a -> Prohibitions.whenAffirmative(a.get(0), m(a.get(1))));
    }

    static boolean isThrow(Object o) { return o instanceof Map && ((Map<?, ?>) o).containsKey("$throws"); }

    static String show(Object o) { return isThrow(o) ? "THROWS" : Json.canonicalize(o); }

    /** Replays the cases of {@code fn}, adding one line per divergence to {@code bad}; returns how many ran. */
    static int diverge(String fn, boolean exotic, List<String> bad) throws Exception {
        Fn f = IMPL.get(fn);
        int ran = 0;
        for (Map<String, Object> c : K05Oracle.of(MODULE, fn)) {
            if (((String) c.get("name")).startsWith(fn + "/x:") != exotic) continue;
            ran++;
            String want = show(c.get("out"));
            String got;
            try { got = Json.canonicalize(f.apply((List<?>) c.get("args"))); } catch (Throwable t) { got = "THROWS"; }
            if (!want.equals(got)) bad.add(c.get("name") + "\n  want: " + cut(want) + "\n  got:  " + cut(got));
        }
        return ran;
    }

    static String cut(String s) { return s.length() > 400 ? s.substring(0, 400) : s; }

    static void check(String fn) throws Exception {
        List<String> bad = new ArrayList<>();
        int ran = diverge(fn, false, bad);
        assertTrue(ran > 0, fn + ": no cases");
        assertTrue(bad.isEmpty(), fn + ": " + bad.size() + " of " + ran + " divergent case(s):\n" + String.join("\n", bad.subList(0, Math.min(bad.size(), 25))));
    }

    @Test void validateInvariant() throws Exception { check("validateInvariant"); }
    @Test void validateConstitution() throws Exception { check("validateConstitution"); }
    @Test void stateProblem() throws Exception { check("stateProblem"); }
    @Test void canonicalState() throws Exception { check("canonicalState"); }
    @Test void stateDigest() throws Exception { check("stateDigest"); }
    @Test void tickState() throws Exception { check("tickState"); }
    @Test void emptyState() throws Exception { check("emptyState"); }
    @Test void checkProhibitions() throws Exception { check("checkProhibitions"); }
    @Test void advanceStateStrict() throws Exception { check("advanceStateStrict"); }
    @Test void proveSafety() throws Exception { check("proveSafety"); }
    @Test void verifySafetyEvidence() throws Exception { check("verifySafetyEvidence"); }
    @Test void safetyBindingId() throws Exception { check("safetyBindingId"); }
    @Test void signSafetyEvidence() throws Exception { check("signSafetyEvidence"); }
    @Test void verifySignedSafetyEvidence() throws Exception { check("verifySignedSafetyEvidence"); }
    @Test void checkAndAdvance() throws Exception { check("checkAndAdvance"); }
    @Test void verifyConstitution() throws Exception { check("verifyConstitution"); }
    @Test void constitutionId() throws Exception { check("constitutionId"); }
    @Test void whenAffirmative() throws Exception { check("whenAffirmative"); }

    /** Inputs the canonical hash refuses (-0, huge integers, lone surrogates): every fn, replayed together. */
    @Test void exoticCases() throws Exception {
        List<String> bad = new ArrayList<>();
        int ran = 0;
        for (String fn : IMPL.keySet()) ran += diverge(fn, true, bad);
        assertTrue(ran > 0, "no exotic cases");
        assertTrue(bad.isEmpty(), bad.size() + " of " + ran + " divergent exotic case(s):\n" + String.join("\n", bad.subList(0, Math.min(bad.size(), 25))));
    }
}
